package com.acaivis.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="order_status_history") public class OrderStatusHistory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="order_id",nullable=false) private Order order; @Enumerated(EnumType.STRING) @Column(nullable=false) private OrderStatus status; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; public OrderStatusHistory(){} public OrderStatusHistory(Order order,OrderStatus status,LocalDateTime createdAt){this.order=order;this.status=status;this.createdAt=createdAt;} public OrderStatus getStatus(){return status;} public LocalDateTime getCreatedAt(){return createdAt;} }
